export function getMarketCap(stockOrSymbol) {
  const sym = typeof stockOrSymbol === 'string' ? stockOrSymbol : stockOrSymbol?.symbol;
  if (!sym) {
    return {
      category: 'SMALL',
      label: 'Small Cap',
      badge: 'SMALL',
      mktCapCr: 3500,
      mkt_cap_cr: 3500,
      color: '#FEE360',
      badgeColor: '#FEE360',
      isPenny: false
    };
  }
  const mapped = MKT_CAP_MAP[sym];
  if (mapped) {
    return {
      ...mapped,
      color: mapped.badgeColor || '#00E887',
      mkt_cap_cr: mapped.mktCapCr
    };
  }
  
  // Fallback heuristic based on price and weight
  if (typeof stockOrSymbol === 'object') {
    if (stockOrSymbol.mkt_cap_category) {
      const cat = stockOrSymbol.mkt_cap_category;
      const color = cat === 'LARGE' ? '#00E887' :
                    cat === 'MID' ? '#3657FF' :
                    cat === 'PENNY' ? '#FF5959' : '#FEE360';
      const mcap = stockOrSymbol.mkt_cap_cr || 5000;
      return {
        category: cat,
        label: stockOrSymbol.mkt_cap_label || cat,
        badge: cat,
        mktCapCr: mcap,
        mkt_cap_cr: mcap,
        color,
        badgeColor: color,
        isPenny: cat === 'PENNY' || !!stockOrSymbol.is_penny
      };
    }
    if ((stockOrSymbol.ltp || 0) <= 35) {
      return {
        category: 'PENNY',
        label: 'Penny Stock',
        badge: 'PENNY',
        mktCapCr: 850,
        mkt_cap_cr: 850,
        color: '#FF5959',
        badgeColor: '#FF5959',
        isPenny: true
      };
    }
    if (stockOrSymbol.nifty50 || (stockOrSymbol.weight && stockOrSymbol.weight >= 1.0)) {
      return {
        category: 'LARGE',
        label: 'Large Cap',
        badge: 'LARGE',
        mktCapCr: 85000,
        mkt_cap_cr: 85000,
        color: '#00E887',
        badgeColor: '#00E887',
        isPenny: false
      };
    }
  }
  return {
    category: 'SMALL',
    label: 'Small Cap',
    badge: 'SMALL',
    mktCapCr: 3500,
    mkt_cap_cr: 3500,
    color: '#FEE360',
    badgeColor: '#FEE360',
    isPenny: false
  };
}

export function filterByMarketCap(stocks = [], selectedCap = 'ALL') {
  if (!selectedCap || selectedCap === 'ALL') return stocks;
  return stocks.filter(s => {
    const info = getMarketCap(s);
    if (selectedCap === 'PENNY') {
      return info.category === 'PENNY' || (s.ltp && s.ltp <= 35);
    }
    return info.category === selectedCap;
  });
}
